import pytest
from pomodoro_cli.config import PomodoroConfig

class TestPomodoroConfigDefaults:
    def test_default_values(self):
        cfg = PomodoroConfig()
        assert cfg.work_duration == 25 * 60
        assert cfg.short_break_duration == 5 * 60
        assert cfg.long_break_duration == 15 * 60
        assert cfg.sessions_before_long_break == 4

class TestPomodoroConfigCustomValues:
    def test_custom_values(self):
        cfg = PomodoroConfig(
            work_duration=30 * 60,
            short_break_duration=3 * 60,
            long_break_duration=20 * 60,
            sessions_before_long_break=5,
        )
        assert cfg.work_duration == 30 * 60
        assert cfg.short_break_duration == 3 * 60
        assert cfg.long_break_duration == 20 * 60
        assert cfg.sessions_before_long_break == 5

class TestPomodoroConfigFrozen:
    def test_cannot_mutate(self):
        cfg = PomodoroConfig()
        with pytest.raises(Exception):  # FrozenInstanceError
            cfg.work_duration = 10 * 60

class TestPomodoroConfigValidationZeroDuration:
    @pytest.mark.parametrize(
        "kwargs",
        [
            {"work_duration": 0},
            {"short_break_duration": 0},
            {"long_break_duration": 0},
        ],
    )
    def test_zero_duration_raises(self, kwargs):
        with pytest.raises(ValueError):
            PomodoroConfig(**kwargs)

class TestPomodoroConfigValidationNegativeDuration:
    @pytest.mark.parametrize(
        "kwargs",
        [
            {"work_duration": -1},
            {"short_break_duration": -5},
            {"long_break_duration": -30},
        ],
    )
    def test_negative_duration_raises(self, kwargs):
        with pytest.raises(ValueError):
            PomodoroConfig(**kwargs)

class TestPomodoroConfigValidationSessionsBeforeLongBreak:
    @pytest.mark.parametrize("value", [0, -1])
    def test_invalid_sessions_before_long_break_raises(self, value):
        with pytest.raises(ValueError):
            PomodoroConfig(sessions_before_long_break=value)

    def test_minimum_valid_sessions_before_long_break(self):
        cfg = PomodoroConfig(sessions_before_long_break=1)
        assert cfg.sessions_before_long_break == 1

