@dataclass(frozen=True)
class PomodoroConfig:
    """Configuration for a Pomodoro timer session.

    All fields have sensible defaults and the class is immutable (frozen).
    Raises ValueError on construction if any duration is non-positive.
    """

    work_duration: int = 25 * 60       # seconds — default 25 min
    short_break_duration: int = 5 * 60  # seconds — default 5 min
    long_break_duration: int = 15 * 60  # seconds — default 15 min
    sessions_before_long_break: int = 4  # number of work sessions before a long break

    def __post_init__(self) -> None:
        if self.work_duration <= 0:
            raise ValueError("work_duration must be positive")
        if self.short_break_duration <= 0:
            raise ValueError("short_break_duration must be positive")
        if self.long_break_duration <= 0:
            raise ValueError("long_break_duration must be positive")
        if self.sessions_before_long_break < 1:
            raise ValueError("sessions_before_long_break must be at least 1")

